insert into public.football_team_profiles (team_id, nickname, tags, intro) values
(503, '드라공이스', '{포르투,에스타디우 두 드라강,1893년 창단}', $t$<p>FC 포르투는 포르투갈 북부의 항구 도시 포르투를 대표하는 구단으로, 구단 엠블럼의 용에서 따온 "드라공이스(용들)"라는 별명으로 불립니다. 1987년 유러피언컵 우승에 이어 2003년 UEFA컵, 2004년 조제 모리뉴 감독과 함께 챔피언스리그 정상에 올랐고, 2011년에는 유로파리그까지 차지하며 포르투갈에서 가장 많은 유럽 트로피를 모은 구단이 됐습니다. 리스본의 벤피카와 맞붙는 "오 클라시쿠"는 포르투갈 축구 최대의 라이벌전으로 꼽힙니다.</p><p>토리코리 관전 포인트: 포르투는 리그 하위권 팀을 상대로 승점을 거의 흘리지 않는 편이라, 경기당 승점과 무실점 비율이 우승 경쟁의 기준선이 됩니다. 홈과 원정 경기당 승점 차이가 벌어지는 시즌에는 빅3 맞대결 결과가 순위를 가르니 해당 일정을 따로 확인해 보세요.</p>$t$),
(1903, '아길리아스', '{리스본,에스타디우 다 루스,1904년 창단}', $t$<p>벤피카는 수도 리스본을 연고로 하는 포르투갈 최대 인기 구단으로, 엠블럼의 독수리에서 따온 "아길리아스(독수리들)"라는 별명을 갖고 있습니다. 1961년과 1962년 유러피언컵을 2년 연속 들어 올렸고, 전설적인 공격수 에우제비우가 이 시기 구단의 상징이었습니다. 포르투갈 리그 최다 우승 구단이며, 스포르팅과의 리스본 더비, 포르투와의 오 클라시쿠 모두 시즌 판도를 좌우하는 경기입니다.</p><p>토리코리 관전 포인트: 벤피카는 홈 경기당 승점이 매우 높은 팀이라, 원정에서 얼마나 승점을 지키느냐가 시즌 성적을 결정하는 경우가 많습니다. 경기당 득점이 많은 팀인 만큼 2.5골 오버 비율과 후반 득점 비중을 함께 보면 경기 흐름을 읽기 쉽습니다.</p>$t$),
(498, '레옹이스', '{리스본,에스타디우 주제 알발라드,1906년 창단}', $t$<p>스포르팅 CP는 리스본을 연고로 하는 구단으로, 엠블럼의 사자에서 따온 "레옹이스(사자들)"라는 별명으로 불립니다. 유소년 아카데미가 특히 유명해 루이스 피구와 크리스티아누 호날두 같은 세계적인 선수를 길러 냈습니다. 1964년 컵위너스컵 우승 경험이 있으며, 2020-21 시즌 19년 만에 리그 정상에 오른 데 이어 2023-24, 2024-25 시즌에는 리그 2연패를 달성했습니다. 벤피카와의 리스본 더비는 포르투갈에서 가장 뜨거운 경기 가운데 하나입니다.</p><p>토리코리 관전 포인트: 스포르팅은 전방 압박으로 이른 시간에 득점을 만드는 경기가 많아 전반 득점 비중을 눈여겨볼 만합니다. 최근 5경기에서 무실점 경기가 이어지는지 함께 확인하면 팀 컨디션을 빠르게 파악할 수 있습니다.</p>$t$),
(5613, '아르세날리스타스', '{브라가,에스타디우 무니시팔 드 브라가,1921년 창단}', $t$<p>브라가는 포르투갈 북부 민뉴 지방의 중심 도시 브라가를 연고로 하는 구단으로, 아스널을 닮은 붉은 유니폼 덕분에 "아르세날리스타스"라는 별명을 얻었습니다. 홈구장은 유로 2004를 위해 채석장 암벽을 깎아 지은 독특한 경기장으로 유명합니다. 2011년 유로파리그 결승에 올랐고, 2016년에는 포르투갈컵을 들어 올렸습니다. 인근 기마랑이스의 비토리아와 치르는 민뉴 더비는 지역 자존심이 걸린 경기입니다.</p><p>토리코리 관전 포인트: 브라가는 빅3 다음 자리를 노리는 팀이라 중하위권 상대 경기당 승점이 순위를 결정합니다. 양팀 득점 비율이 높은 편인지, 원정에서 실점이 늘어나는지를 함께 보면 경기 성향을 가늠하기 좋습니다.</p>$t$),
(5543, '콘키스타도르스', '{기마랑이스,에스타디우 동 아폰수 엔히케스,1922년 창단}', $t$<p>비토리아 기마랑이스는 "포르투갈이 태어난 도시"로 불리는 기마랑이스를 연고로 하는 구단입니다. 포르투갈 초대 국왕 아폰수 엔히케스와 도시의 역사에서 따온 "콘키스타도르스(정복자들)"라는 별명을 갖고 있고, 홈구장 이름도 그에게서 따왔습니다. 2013년 포르투갈컵 결승에서 벤피카를 꺾고 첫 우승을 차지했으며, 열정적인 홈 관중으로 유명합니다. 이웃 도시 브라가와의 민뉴 더비가 가장 큰 라이벌전입니다.</p><p>토리코리 관전 포인트: 비토리아는 홈 관중의 응원 덕분에 홈 경기당 승점이 원정보다 눈에 띄게 높은 시즌이 많습니다. 후반 실점이 잦은 시기에는 리드를 지키지 못하는 경기가 늘어나니 전반·후반 득실점을 나눠 보세요.</p>$t$),
(5529, null, '{푼샬,에스타디우 다 마데이라,1910년 창단}', $t$<p>나시오날은 대서양의 마데이라섬 푼샬을 연고로 하는 구단으로, 흑백 유니폼을 입습니다. 푼샬 출신인 크리스티아누 호날두가 스포르팅으로 가기 전 유소년 시절을 보낸 구단으로도 알려져 있습니다. 2000년대에는 1부 리그 상위권에 오르며 유럽 대항전에 나서기도 했습니다. 같은 섬의 마리티무와 치르는 마데이라 더비가 대표적인 라이벌전입니다.</p><p>토리코리 관전 포인트: 섬 원정이라는 특성 때문에 상대 팀이 이동 부담을 안고 오는 만큼, 나시오날은 홈과 원정 경기당 승점 차이를 꼭 확인해야 하는 팀입니다. 최근 5경기 흐름과 무실점 비율을 함께 보면 잔류 경쟁에서의 위치를 가늠할 수 있습니다.</p>$t$),
(5575, null, '{푼샬,에스타디우 두 마리티무,1910년 창단}', $t$<p>마리티무는 마데이라섬 푼샬을 연고로 하는 구단으로, 녹색과 붉은색 유니폼으로 잘 알려져 있습니다. 오랜 기간 1부 리그에 꾸준히 머물며 여러 차례 유럽 대항전에 나섰고, 섬 전체의 큰 지지를 받는 구단입니다. 같은 도시의 나시오날과 맞붙는 마데이라 더비는 섬 팬들이 가장 기다리는 경기입니다.</p><p>토리코리 관전 포인트: 마리티무 역시 섬 홈경기의 이점이 큰 팀이라 홈 경기당 승점을 먼저 보는 것이 좋습니다. 득점이 적고 접전이 많은 시즌에는 2.5골 오버 비율이 낮게 나타나는지 확인해 보세요.</p>$t$),
(583, null, '{모레이라 드 코네구스,코멘다도르 조아킹 드 알메이다 프레이타스 경기장,1938년 창단}', $t$<p>모레이렌스는 기마랑이스 인근의 작은 마을 모레이라 드 코네구스를 연고로 하는 구단입니다. 규모는 작지만 1부 리그에서 꾸준히 경쟁해 왔고, 2017년 리그컵 결승에서 브라가를 꺾고 구단 역사상 첫 주요 트로피를 들어 올렸습니다. 작은 경기장에서 끈끈한 경기를 펼치는 팀으로 알려져 있습니다.</p><p>토리코리 관전 포인트: 모레이렌스는 실점을 최소화하며 승점을 쌓는 경기가 많아 무실점 비율과 경기당 실점을 먼저 보는 것이 좋습니다. 무승부가 많은 시기에는 양팀 득점 비율도 함께 낮아지는지 살펴보세요.</p>$t$),
(5530, null, '{폰타델가다,에스타디우 드 상 미겔,1921년 창단}', $t$<p>산타 클라라는 대서양 아소르스 제도 상 미겔섬의 폰타델가다를 연고로 하는 구단입니다. 아소르스 제도를 대표하는 구단으로, 1990년대 후반 처음 1부 리그 무대를 밟았습니다. 본토에서 비행기로 이동해야 하는 먼 원정지라 상대 팀에게는 까다로운 일정으로 꼽힙니다.</p><p>토리코리 관전 포인트: 원거리 원정을 오는 상대를 맞는 만큼 산타 클라라는 홈 경기당 승점이 성적의 핵심입니다. 반대로 본토 원정이 몰리는 시기에는 최근 5경기 폼이 흔들리는지 확인해 보세요.</p>$t$),
(712, null, '{아로카,아로카 시립 경기장,1952년 창단}', $t$<p>아로카는 포르투갈 북부 아베이루 지방의 작은 산간 도시 아로카를 연고로 하는 구단입니다. 하부 리그에서 출발해 2010년대에 1부 리그로 올라왔고, 2016년에는 유로파리그 예선에 나서며 구단 역사상 첫 유럽 무대를 경험했습니다. 작은 도시 구단의 성장 사례로 자주 언급됩니다.</p><p>토리코리 관전 포인트: 아로카는 경기마다 득점과 실점의 편차가 큰 편이라 2.5골 오버 비율과 양팀 득점 비율을 함께 보는 것이 좋습니다. 전반과 후반 득실점을 나눠 보면 어느 시간대에 흔들리는지 확인할 수 있습니다.</p>$t$),
(5527, null, '{비제우,에스타디우 두 폰텔루,1914년 창단}', $t$<p>아카데미쿠 드 비제우는 포르투갈 중부 내륙 도시 비제우를 연고로 하는 구단입니다. 1914년에 뿌리를 둔 옛 아카데미쿠의 전통을 이어 2005년 지금의 구단 체제로 다시 출발했으며, 주로 2부 리그에서 경쟁해 왔습니다. 비제우 지역을 대표하는 구단으로 지역 팬들의 지지를 받고 있습니다.</p><p>토리코리 관전 포인트: 1부 무대 경험이 적은 팀은 상위권 상대에게 실점이 몰리는 경우가 많아 경기당 실점과 무실점 비율을 먼저 확인하는 것이 좋습니다. 홈 경기당 승점이 잔류 경쟁의 버팀목이 되는지도 함께 살펴보세요.</p>$t$),
(7822, null, '{알베르카 두 히바테주,FC 알베르카 경기장,1939년 창단}', $t$<p>알베르카는 리스본 북쪽 근교의 알베르카 두 히바테주를 연고로 하는 구단입니다. 1990년대 후반부터 2000년대 초반까지 1부 리그에서 뛰었고, 당시 벤피카와 긴밀한 협력 관계를 맺어 젊은 선수들이 경험을 쌓는 무대가 되기도 했습니다. 오랜 하부 리그 생활을 거쳐 다시 1부 무대를 노려 온 구단입니다.</p><p>토리코리 관전 포인트: 승격 팀은 시즌 초반 흐름이 잔류를 크게 좌우하므로 최근 5경기 성적과 경기당 승점을 함께 보는 것이 좋습니다. 원정 경기당 승점이 크게 떨어지는지도 눈여겨보세요.</p>$t$),
(582, '카나리뉴스', '{이스토릴,에스타디우 안토니우 코잉브라 다 모타,1939년 창단}', $t$<p>이스토릴 프라이아는 리스본 서쪽 해안의 휴양 도시 이스토릴을 연고로 하는 구단입니다. 노란 유니폼 덕분에 "카나리뉴스(카나리아들)"라는 별명으로 불립니다. 2010년대 초반 1부 리그 상위권에 오르며 유로파리그 무대를 밟았고, 젊은 선수를 키워 큰 구단으로 보내는 팀으로도 알려져 있습니다.</p><p>토리코리 관전 포인트: 이스토릴은 중위권과 하위권을 오가는 시즌이 많아 최근 5경기 흐름을 확인하는 것이 중요합니다. 양팀 득점 비율이 높은 시기에는 경기당 실점도 함께 늘어나는지 살펴보세요.</p>$t$),
(9136, null, '{아마도라,에스타디우 주제 고메스,2020년 창단}', $t$<p>이스트렐라 다 아마도라는 리스본 근교 도시 아마도라를 연고로 하는 구단입니다. 1990년 포르투갈컵 우승을 차지했던 옛 이스트렐라 다 아마도라가 재정난으로 해체된 뒤, 2020년 출범한 새 구단이 그 이름과 홈구장, 전통을 이어받았습니다. 새 출발 이후 빠르게 하부 리그를 거쳐 1부 무대에 올라왔습니다.</p><p>토리코리 관전 포인트: 이스트렐라는 득점이 많지 않은 접전을 자주 치르는 편이라 2.5골 오버 비율이 낮게 나오는지 확인해 보세요. 무실점 경기가 이어지는 시기에 승점이 몰리는 경우가 많습니다.</p>$t$),
(5533, '갈루스', '{바르셀루스,에스타디우 시다드 드 바르셀루스,1924년 창단}', $t$<p>질 비센트는 포르투갈 북부 민뉴 지방의 도시 바르셀루스를 연고로 하는 구단으로, 구단 이름은 포르투갈 연극의 아버지로 불리는 극작가 질 비센트에서 따왔습니다. 포르투갈의 상징인 "바르셀루스의 수탉" 전설에서 따온 "갈루스(수탉들)"라는 별명을 갖고 있습니다. 2000년대 중반 행정 문제로 하부 리그로 내려가는 아픔을 겪었지만 다시 1부 리그로 돌아왔습니다.</p><p>토리코리 관전 포인트: 질 비센트는 홈에서 승점을 착실히 쌓는 시즌이 많아 홈·원정 경기당 승점을 나눠 보는 것이 좋습니다. 후반 득점 비중이 높은 시기에는 경기 막판 결과가 뒤집히는 경우가 잦습니다.</p>$t$),
(6618, '간수스', '{리스본,에스타디우 피나 마니크,1920년 창단}', $t$<p>카사 피아는 리스본의 오래된 보호시설 카사 피아 출신들이 세운 구단으로, "간수스(거위들)"라는 별명으로 불립니다. 창립 멤버 가운데 한 명인 칸디두 드 올리베이라는 훗날 포르투갈 대표팀을 이끌었고, 포르투갈 슈퍼컵의 이름도 그에게서 따왔습니다. 오랜 하부 리그 생활 끝에 2020년대 들어 1부 리그로 돌아왔습니다.</p><p>토리코리 관전 포인트: 카사 피아는 수비를 단단히 한 뒤 역습으로 승점을 노리는 경기가 많아 무실점 비율을 먼저 보는 것이 좋습니다. 최근 5경기에서 득점 없는 경기가 이어지는지도 함께 확인해 보세요.</p>$t$),
(5531, null, '{빌라노바 드 파말리캉,에스타디우 무니시팔 22 드 주뉴,1931년 창단}', $t$<p>파말리캉은 포르투갈 북부 민뉴 지방의 빌라노바 드 파말리캉을 연고로 하는 구단입니다. 오랫동안 하부 리그에 머물다 2019년 25년 만에 1부 리그로 복귀했고, 이후 젊은 선수들을 적극적으로 기용하는 팀으로 주목받았습니다. 유망주를 키워 큰 구단으로 보내는 운영 방식으로 알려져 있습니다.</p><p>토리코리 관전 포인트: 젊은 선수 위주의 팀은 경기마다 기복이 커 최근 5경기 성적과 경기당 승점을 함께 보는 것이 좋습니다. 전반 실점이 많은 시기에는 경기 초반 흐름을 내주는 경우가 잦으니 전반·후반 득실점을 확인해 보세요.</p>$t$),
(496, null, '{빌라 두 콘드,에스타디우 두 히우 아브,1939년 창단}', $t$<p>히우 아브는 포르투 북쪽 해안 도시 빌라 두 콘드를 연고로 하는 구단입니다. 1부 리그 중위권에서 꾸준히 경쟁해 왔고, 2013-14 시즌에는 포르투갈컵과 리그컵 결승에 모두 올랐습니다. 이 활약을 바탕으로 유로파리그 무대도 밟으며 작은 도시 구단의 저력을 보여 줬습니다.</p><p>토리코리 관전 포인트: 히우 아브는 홈과 원정 성적 차이가 뚜렷한 시즌이 많아 홈·원정 경기당 승점을 나눠 보는 것이 좋습니다. 양팀 득점 비율과 2.5골 오버 비율을 함께 보면 경기 성향을 파악하기 쉽습니다.</p>$t$)
